package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.net.*;import android.widget.*;import android.view.*;import android.provider.*;import android.database.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import ru.truetv.bridge.*;
/** Real receiver Activity + TLS + public Downloads. Disposable VM, no owner device. */
public final class SessionCheck extends Instrumentation {
 private Context c;private ShareSettingsActivity screen;private final ExecutorService pool=Executors.newCachedThreadPool();private final StringBuilder log=new StringBuilder();private int checks;private String prefix;private final ArrayList<Uri> saved=new ArrayList<>();private Identity phone,tv;private byte[] payload;
 public void onCreate(Bundle b){super.onCreate(b);start();}private Object f(Object o,String n)throws Exception{Field x=o.getClass().getDeclaredField(n);x.setAccessible(true);return x.get(o);}private void main(Runnable a){runOnMainSync(a);waitForIdleSync();}private void check(boolean a,String text){log.append(a?"PASS ":"FAIL ").append(text).append('\n');checks++;if(!a)throw new AssertionError(text);}interface Wait{boolean ok()throws Exception;}private void until(Wait w)throws Exception{long end=SystemClock.uptimeMillis()+25000;while(!w.ok()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(60);}check(w.ok(),"await condition");}
 private void shot(String name)throws Exception{Thread.sleep(500);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();if(b!=null)try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 private Button button(String n)throws Exception{return (Button)f(screen,n);}private int port()throws Exception{Transfer.Receiver r=(Transfer.Receiver)f(screen,"receiver");return r==null?0:r.port();}
 private void startWindow()throws Exception{screen=(ShareSettingsActivity)startActivitySync(new Intent(c,ShareSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));until(()->port()>0);}
 private Future<Boolean> send(int port,String name,byte[] bytes){return pool.submit(()->{try(Transfer.Sender s=new Transfer.Sender()){s.send(phone,InetAddress.getLoopbackAddress(),port,tv.fingerprint(),new Wire.Offer("Phone fixture",Arrays.asList(new Wire.Item(name,"application/octet-stream",bytes.length))),i->new ByteArrayInputStream(bytes),new Transfer.ClientEvents(){public void waiting(String a,String b,String x){}public void accepted(String f){}public void update(int i,String n,long a,long b){}});return true;}catch(Exception e){log.append("SEND ").append(e.getMessage()).append('\n');return false;}});}
 private ArrayList<Uri> downloads()throws Exception{ArrayList<Uri> out=new ArrayList<>();if(Build.VERSION.SDK_INT>=29){try(Cursor q=c.getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name","is_pending"},"_display_name LIKE ?",new String[]{prefix+"%"},null)){while(q!=null&&q.moveToNext()){check(q.getInt(2)==0,"published row is not pending");out.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,q.getLong(0)));}}}else{File[] all=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).listFiles();if(all!=null)for(File x:all)if(x.getName().startsWith(prefix))out.add(Uri.fromFile(x));}for(Uri u:out)if(!saved.contains(u))saved.add(u);return out;}
 private byte[] read(Uri uri)throws Exception{try(InputStream in="file".equals(uri.getScheme())?new FileInputStream(uri.getPath()):c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 public void onStart(){Bundle result=new Bundle();boolean oldAuto=false;String before=null;try{c=getTargetContext();if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");prefix="totv231-"+System.currentTimeMillis();VmWindows.prepare(this);before=Settings.Secure.getString(c.getContentResolver(),"enabled_accessibility_services");oldAuto=c.getSharedPreferences("totv_window",0).getBoolean("automatic",false);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",false).commit();
  HomeActivity home=VmWindows.home(this);check(home.header.getChildAt(2).getContentDescription().toString().contains("Wi-Fi"),"antenna immediately follows file manager");final ActivityMonitor monitor=new ActivityMonitor(ShareSettingsActivity.class.getName(),null,false);addMonitor(monitor);main(()->home.header.getChildAt(2).performClick());screen=(ShareSettingsActivity)waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);check(screen!=null,"desktop antenna opens receive popup directly");until(()->port()>0);tv=Identity.load(new File(c.getFilesDir(),"to-tv-identity"));phone=Identity.load(new File(c.getCacheDir(),"session231-phone"));payload=new byte[2*1024*1024+39];new Random(231).nextBytes(payload);int firstPort=port();Future<Boolean> first=send(firstPort,prefix+".bin",payload);until(()->f(screen,"decision")!=null);check(downloads().isEmpty(),"no file before confirmation");check(button("accept").getVisibility()==View.VISIBLE&&button("reject").getVisibility()==View.VISIBLE,"only Accept/Decline for incoming request");shot("2.2.1-request-api"+Build.VERSION.SDK_INT+".png");main(()->{try{button("accept").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(first.get(40,TimeUnit.SECONDS),"manual accept writes real TLS payload");until(()->button("open").getVisibility()==View.VISIBLE);check(Arrays.equals(read(downloads().get(0)),payload),"public Downloads exact bytes");check(button("location").getVisibility()==View.VISIBLE,"result offers Open file / Show in folder");check(f(screen,"decision")==null,"completed decision cleared");shot("2.2.1-result-api"+Build.VERSION.SDK_INT+".png");
  Future<Boolean> denied=send(firstPort,prefix+".bin",payload);until(()->f(screen,"decision")!=null);main(()->{try{button("reject").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(!denied.get(20,TimeUnit.SECONDS)&&downloads().size()==1,"same device asks again; decline preserves existing file");until(()->((CheckBox)f(screen,"automatic")).isEnabled());main(()->{try{((CheckBox)f(screen,"automatic")).setChecked(true);}catch(Exception e){throw new RuntimeException(e);}});
  for(int i=0;i<4;i++){Future<Boolean> retry=send(firstPort,prefix+".bin",payload);check(retry.get(40,TimeUnit.SECONDS),"repeat transfer "+i+" without restarting popup");until(()->button("open").getVisibility()==View.VISIBLE);check(downloads().size()==i+2,"collision keeps each completed file");}
  main(()->screen.finish());until(()->port()==0);check(!send(firstPort,prefix+"-closed.bin",payload).get(12,TimeUnit.SECONDS),"closed popup refuses new connection");startWindow();int secondPort=port();main(()->{try{((CheckBox)f(screen,"automatic")).setChecked(false);}catch(Exception e){throw new RuntimeException(e);}});Future<Boolean> closing=send(secondPort,prefix+"-close.bin",payload);until(()->f(screen,"decision")!=null);main(()->screen.finish());check(!closing.get(15,TimeUnit.SECONDS),"closing pending question rejects and closes socket");check(downloads().size()==5,"closed request never publishes");startWindow();main(()->{try{((CheckBox)f(screen,"automatic")).setChecked(true);}catch(Exception e){throw new RuntimeException(e);}});check(send(port(),prefix+"-empty.bin",new byte[0]).get(20,TimeUnit.SECONDS),"reopen after close receives empty file");until(()->button("location").getVisibility()==View.VISIBLE);
  final java.util.concurrent.atomic.AtomicReference<Intent> opened=new java.util.concurrent.atomic.AtomicReference<>();ActivityMonitor viewMonitor=new ActivityMonitor(){public ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){opened.set(new Intent(intent));return new ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};addMonitor(viewMonitor);main(()->{try{button("open").performClick();}catch(Exception e){throw new RuntimeException(e);}});until(()->opened.get()!=null);removeMonitor(viewMonitor);Intent view=opened.get();check("content".equals(view.getData().getScheme())&&view.getClipData()!=null,"Open file passes a real content URI in data and ClipData");check((view.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&(view.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0,"Open file grants read only");until(()->port()==0);startWindow();check(send(port(),prefix+"-last.bin",new byte[]{1,2,3}).get(20,TimeUnit.SECONDS),"receive after opening file works again");until(()->button("location").getVisibility()==View.VISIBLE);

  ActivityMonitor files=new ActivityMonitor(FileActivity.class.getName(),null,false);addMonitor(files);main(()->{try{button("location").performClick();}catch(Exception e){throw new RuntimeException(e);}});FileActivity manager=(FileActivity)waitForMonitorWithTimeout(files,15000);removeMonitor(files);check(manager!=null&&manager.getIntent().getBooleanExtra("downloads",false),"Show in folder opens actual Downloads manager");check(port()==0,"Show in folder ends reception");if(manager!=null)main(manager::finish);check(Objects.equals(before,Settings.Secure.getString(c.getContentResolver(),"enabled_accessibility_services")),"accessibility unchanged");result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter out=new StringWriter();e.printStackTrace(new PrintWriter(out));log.append(out);result.putBoolean("passed",false);}finally{try{if(screen!=null)main(screen::finish);downloads();for(Uri u:saved)if("file".equals(u.getScheme()))new File(u.getPath()).delete();else c.getContentResolver().delete(u,null,null);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",oldAuto).commit();}catch(Exception e){log.append("CLEANUP ").append(e);}pool.shutdownNow();}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
